package com.payflow.engineeringlab;

import com.payflow.common.ApiException;
import com.payflow.config.DemoProvisioningService;
import com.payflow.ledger.LedgerRepository;
import com.payflow.reconciliation.ReconciliationService;
import com.payflow.transaction.TransactionEngine;
import com.payflow.transaction.TransactionRepository;
import com.payflow.user.User;
import com.payflow.wallet.WalletRepository;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

@Service @ConditionalOnProperty(name="payflow.lab-enabled",havingValue="true")
public class LabScenarioService {
  public record Result(String scenario,boolean passed,long durationMillis,Map<String,Object> expected,Map<String,Object> observed,List<String> transactionReferences){}
  private record TransferOutcome(boolean success,String direction,long durationMillis,TransactionEngine.Result result,String error){}
  private final DemoProvisioningService provision;private final TransactionEngine engine;private final WalletRepository wallets;
  private final TransactionRepository transactions;private final LedgerRepository ledger;private final ReconciliationService reconciliation;
  private final Semaphore singleRun=new Semaphore(1);
  public LabScenarioService(DemoProvisioningService p,TransactionEngine e,WalletRepository w,TransactionRepository t,LedgerRepository l,ReconciliationService r){provision=p;engine=e;wallets=w;transactions=t;ledger=l;reconciliation=r;}

  public Result run(String scenario,Long ownerId){if(!singleRun.tryAcquire())throw new ApiException(HttpStatus.CONFLICT,"LAB_BUSY","Another controlled scenario is running");try{long start=System.nanoTime();Result base=switch(scenario){case"concurrent-credits"->credits(ownerId,2);case"concurrent-credits-stress"->credits(ownerId,50);case"double-spend"->doubleSpend(ownerId,2);case"double-spend-stress"->doubleSpend(ownerId,50);case"idempotency"->idempotency(ownerId);case"rollback"->rollback(ownerId);case"lock-ordering"->opposite(ownerId);case"reconciliation"->reconcile();default->throw new ApiException(HttpStatus.NOT_FOUND,"SCENARIO_NOT_FOUND","Unknown lab scenario");};return new Result(base.scenario(),base.passed(),elapsed(start),base.expected(),base.observed(),base.transactionReferences());}finally{singleRun.release();}}

  private Result credits(Long owner,int requests){boolean stress=requests==50;List<User>a=accounts(owner,stress?"credit-stress":"credit",stress?51:3);User receiver=a.get(0);fund(receiver,100_000);List<Callable<TransactionEngine.Result>>calls=new ArrayList<>();if(stress){for(int i=1;i<a.size();i++){User sender=a.get(i);fund(sender,10_000);calls.add(()->engine.transfer(sender,id(receiver),10_000,null,key(owner)));}}else{fund(a.get(1),50_000);fund(a.get(2),30_000);calls.add(()->engine.transfer(a.get(1),id(receiver),50_000,null,key(owner)));calls.add(()->engine.transfer(a.get(2),id(receiver),30_000,null,key(owner)));}long initial=100_000;List<TransactionEngine.Result>results=parallel(calls);long finalBalance=balance(receiver),expectedBalance=stress?600_000:180_000,postings=ledgerEntries(results);boolean consistent=reconciliation.run().passed();Map<String,Object>expected=ordered("requestsAttempted",requests,"successfulTransfers",requests,"initialReceiverBalancePaise",initial,"finalReceiverBalancePaise",expectedBalance,"transferLedgerEntries",requests*2L,"ledgerConsistent",true);Map<String,Object>observed=ordered("requestsAttempted",requests,"successfulTransfers",results.size(),"initialReceiverBalancePaise",initial,"incomingAmountsPaise",stress?List.of("50 × 10000"):List.of(50_000,30_000),"finalReceiverBalancePaise",finalBalance,"transferLedgerEntries",postings,"ledgerConsistent",consistent);return result(stress?"concurrent-credits-stress":"concurrent-credits",results.size()==requests&&finalBalance==expectedBalance&&postings==requests*2L&&consistent,expected,observed,results);}

  private Result doubleSpend(Long owner,int requests){boolean stress=requests==50;List<User>a=accounts(owner,stress?"debit-stress":"debit",requests+1);User sender=a.get(0);fund(sender,100_000);long amount=stress?10_000:80_000,ledgerBefore=ledger.count();AtomicInteger ok=new AtomicInteger(),rejected=new AtomicInteger(),unexpected=new AtomicInteger();List<Runnable>calls=new ArrayList<>();for(int i=1;i<a.size();i++){Long target=id(a.get(i));calls.add(()->attempt(sender,target,amount,ok,rejected,unexpected));}parallelVoid(calls);long finalBalance=balance(sender),postings=ledger.count()-ledgerBefore;int expectedSuccess=stress?10:1,expectedRejected=requests-expectedSuccess;List<Long>recipientBalances=a.subList(1,a.size()).stream().map(this::balance).toList();long credited=recipientBalances.stream().filter(v->v==amount).count();boolean consistent=reconciliation.run().passed();Map<String,Object>expected=ordered("requestsAttempted",requests,"successfulTransfers",expectedSuccess,"insufficientBalanceRejections",expectedRejected,"unexpectedFailures",0,"initialSenderBalancePaise",100_000,"finalSenderBalancePaise",stress?0:20_000,"transferLedgerEntries",expectedSuccess*2L,"ledgerConsistent",true);Map<String,Object>observed=ordered("requestsAttempted",requests,"successfulTransfers",ok.get(),"insufficientBalanceRejections",rejected.get(),"unexpectedFailures",unexpected.get(),"initialSenderBalancePaise",100_000,"finalSenderBalancePaise",finalBalance,"creditedRecipients",credited,"recipientBalancesPaise",recipientBalances,"transferLedgerEntries",postings,"ledgerConsistent",consistent);boolean pass=ok.get()==expectedSuccess&&rejected.get()==expectedRejected&&unexpected.get()==0&&finalBalance==(stress?0:20_000)&&postings==expectedSuccess*2L&&consistent;return new Result(stress?"double-spend-stress":"double-spend",pass,0,expected,observed,List.of());}

  private Result idempotency(Long owner){List<User>a=accounts(owner,"idem",2);User sender=a.get(0),receiver=a.get(1);fund(sender,100_000);String idem="lab-identical-"+UUID.randomUUID();List<Callable<TransactionEngine.Result>>calls=new ArrayList<>();for(int i=0;i<50;i++)calls.add(()->engine.transfer(sender,id(receiver),20_000,"duplicate",idem));List<TransactionEngine.Result>results=parallel(calls);long unique=results.stream().map(TransactionEngine.Result::reference).distinct().count(),senderFinal=balance(sender),receiverFinal=balance(receiver),postings=ledgerEntries(results);boolean consistent=reconciliation.run().passed();Map<String,Object>expected=ordered("requestsReceived",50,"uniqueCommittedTransactions",1,"replayedResponses",49,"initialSenderBalancePaise",100_000,"initialReceiverBalancePaise",0,"finalSenderBalancePaise",80_000,"finalReceiverBalancePaise",20_000,"transferLedgerEntries",2,"ledgerConsistent",true);Map<String,Object>observed=ordered("requestsReceived",results.size(),"uniqueCommittedTransactions",unique,"replayedResponses",results.size()-unique,"initialSenderBalancePaise",100_000,"initialReceiverBalancePaise",0,"finalSenderBalancePaise",senderFinal,"finalReceiverBalancePaise",receiverFinal,"transferLedgerEntries",postings,"ledgerConsistent",consistent);return result("idempotency",results.size()==50&&unique==1&&senderFinal==80_000&&receiverFinal==20_000&&postings==2&&consistent,expected,observed,results);}

  private Result rollback(Long owner){List<User>a=accounts(owner,"rollback",2);User sender=a.get(0),receiver=a.get(1);fund(sender,100_000);long senderBefore=balance(sender),receiverBefore=balance(receiver),txBefore=transactions.count(),ledgerBefore=ledger.count();String failure="";try{engine.transferWithInjectedFailure(sender,id(receiver),30_000);}catch(Exception e){failure=Objects.toString(e.getMessage(),e.getClass().getSimpleName());}long senderAfter=balance(sender),receiverAfter=balance(receiver),committedTransactions=transactions.count()-txBefore,committedPostings=ledger.count()-ledgerBefore;boolean rolledBack=senderBefore==senderAfter&&receiverBefore==receiverAfter&&committedTransactions==0&&committedPostings==0;Map<String,Object>expected=ordered("transactionFailed",true,"rollbackVerified",true,"senderBalanceAfterPaise",senderBefore,"receiverBalanceAfterPaise",receiverBefore,"committedTransactions",0,"committedLedgerEntries",0);Map<String,Object>observed=ordered("failureStage","after sender debit flush, before transaction completion","failure",failure,"transactionFailed",!failure.isBlank(),"rollbackVerified",rolledBack,"senderBalanceBeforePaise",senderBefore,"senderBalanceAfterPaise",senderAfter,"receiverBalanceBeforePaise",receiverBefore,"receiverBalanceAfterPaise",receiverAfter,"committedTransactions",committedTransactions,"committedLedgerEntries",committedPostings);return new Result("rollback",rolledBack&&!failure.isBlank(),0,expected,observed,List.of());}

  private Result opposite(Long owner){List<User>a=accounts(owner,"opposite",2);User first=a.get(0),second=a.get(1);fund(first,100_000);fund(second,100_000);Long firstId=id(first),secondId=id(second);List<Long>lockOrder=new ArrayList<>(List.of(firstId,secondId));Collections.sort(lockOrder);List<TransferOutcome>outcomes=parallel(List.of(()->transferOutcome(first,secondId,20_000,"A → B"),()->transferOutcome(second,firstId,30_000,"B → A")));List<TransactionEngine.Result>successes=outcomes.stream().filter(TransferOutcome::success).map(TransferOutcome::result).toList();long firstFinal=balance(first),secondFinal=balance(second);List<String>errors=outcomes.stream().filter(x->!x.success()).map(TransferOutcome::error).toList();boolean consistent=reconciliation.run().passed();Map<String,Object>expected=ordered("completedTransfers",2,"unexpectedFailures",0,"aFinalBalancePaise",110_000,"bFinalBalancePaise",90_000,"ledgerConsistent",true);Map<String,Object>observed=ordered("walletIds",List.of(firstId,secondId),"intendedAscendingLockOrder",lockOrder,"directions",outcomes.stream().map(TransferOutcome::direction).toList(),"completionMillis",outcomes.stream().map(TransferOutcome::durationMillis).toList(),"completedTransfers",successes.size(),"unexpectedFailures",errors.size(),"errors",errors,"aInitialBalancePaise",100_000,"bInitialBalancePaise",100_000,"aFinalBalancePaise",firstFinal,"bFinalBalancePaise",secondFinal,"transferLedgerEntries",ledgerEntries(successes),"ledgerConsistent",consistent);return result("lock-ordering",successes.size()==2&&errors.isEmpty()&&firstFinal==110_000&&secondFinal==90_000&&consistent,expected,observed,successes);}

  private Result reconcile(){ReconciliationService.Report report=reconciliation.run();List<Map<String,Object>>comparisons=ledger.balanceComparison().stream().<Map<String,Object>>map(row->ordered("walletReference",row[1].toString(),"storedBalancePaise",((Number)row[2]).longValue(),"calculatedBalancePaise",((Number)row[3]).longValue())).toList();Map<String,Object>expected=ordered("discrepancies",0,"unbalancedTransactions",0,"passed",true);Map<String,Object>observed=ordered("accountsInspected",report.accountsInspected(),"transactionsInspected",report.transactionsInspected(),"ledgerEntriesInspected",report.ledgerEntriesInspected(),"unbalancedTransactions",report.unbalancedTransactions(),"discrepancies",report.discrepancies(),"storedVersusCalculatedBalances",comparisons,"reconciliationDurationMillis",report.durationMillis(),"passed",report.passed());return new Result("reconciliation",report.passed(),0,expected,observed,List.of());}

  private TransferOutcome transferOutcome(User sender,Long destination,long amount,String direction){long start=System.nanoTime();try{return new TransferOutcome(true,direction,elapsed(start),engine.transfer(sender,destination,amount,null,key(sender.getId())),"");}catch(Exception e){return new TransferOutcome(false,direction,elapsed(start),null,e.getClass().getSimpleName()+": "+Objects.toString(e.getMessage(),""));}}
  private List<User>accounts(Long owner,String scenario,int count){List<User>result=new ArrayList<>();String run=UUID.randomUUID().toString().substring(0,8);for(int i=0;i<count;i++)result.add(provision.create("Lab "+scenario+" "+i,scenario+"-"+run+"-"+i+"@lab.local","8"+String.format("%09d",Math.abs(Objects.hash(owner,run,i))%1_000_000_000),UUID.randomUUID().toString(),true));return result;}
  private void fund(User user,long amount){engine.topup(user,amount,"lab-fund-"+user.getId());}private Long id(User user){return wallets.findIdByOwnerId(user.getId()).orElseThrow();}private long balance(User user){return wallets.findByOwnerId(user.getId()).orElseThrow().getBalancePaise();}private String key(Long owner){return"lab-"+owner+"-"+UUID.randomUUID();}private long elapsed(long start){return(System.nanoTime()-start)/1_000_000;}
  private void attempt(User user,Long destination,long amount,AtomicInteger ok,AtomicInteger rejected,AtomicInteger unexpected){try{engine.transfer(user,destination,amount,null,key(user.getId()));ok.incrementAndGet();}catch(ApiException e){if("INSUFFICIENT_BALANCE".equals(e.code()))rejected.incrementAndGet();else unexpected.incrementAndGet();}catch(Exception e){unexpected.incrementAndGet();}}
  private long ledgerEntries(List<TransactionEngine.Result>results){return results.stream().map(TransactionEngine.Result::reference).distinct().map(transactions::findByReference).flatMap(Optional::stream).mapToLong(tx->ledger.countByTransactionId(tx.getId())).sum();}
  private<T>List<T>parallel(List<Callable<T>>tasks){ExecutorService pool=Executors.newFixedThreadPool(Math.min(12,tasks.size()));try{List<Future<T>>futures=pool.invokeAll(tasks,20,TimeUnit.SECONDS);List<T>result=new ArrayList<>();for(Future<T>future:futures){if(future.isCancelled())throw new TimeoutException("Scenario worker timed out");result.add(future.get());}return result;}catch(Exception e){throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,"LAB_FAILURE",Objects.toString(e.getMessage(),e.getClass().getSimpleName()));}finally{pool.shutdownNow();}}
  private void parallelVoid(List<Runnable>tasks){parallel(tasks.stream().<Callable<Object>>map(task->()->{task.run();return null;}).toList());}
  private Result result(String scenario,boolean passed,Map<String,Object>expected,Map<String,Object>observed,List<TransactionEngine.Result>results){return new Result(scenario,passed,0,expected,observed,results.stream().map(x->x.reference().toString()).distinct().toList());}
  private static LinkedHashMap<String,Object>ordered(Object...pairs){LinkedHashMap<String,Object>map=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)map.put((String)pairs[i],pairs[i+1]);return map;}
}
